<?php declare(strict_types=1);
$annualHistory=null;$annualHistoryFailure=null;
try{$annualHistory=$ledger->sourceDecisionHistory($year,$_GET['source_history_page']??'1');}catch(DomainException $ex){$annualHistoryFailure=$ex->getMessage();}
if($annualHistory!==null&&$annualHistory['total']===0)return;$annualHistoryUrl=static fn(int $page):string=>url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'source_history_page'=>(string)$page]);
?>
<details class="card" data-annual-source-history <?= array_key_exists('source_history_page',$_GET)?'open':'' ?>><summary><?= e($annualSourceText('Übernahmen und Berichtigungen')) ?><?= $annualHistory!==null?' ('.$annualHistory['total'].')':'' ?></summary>
<?php if($annualHistoryFailure!==null): ?><p role="alert"><?= e($annualSourceText($annualHistoryFailure)) ?></p><a class="btn btn-outline" href="<?= e($annualHistoryUrl(1)) ?>"><?= e($annualSourceText('Verlauf neu öffnen')) ?></a><?php else: ?>
<?php foreach($annualHistory['items']as$item): ?><article><h3><?= e((new DateTimeImmutable($item['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i').' · '.$annualSourceText($item['operation']==='correct'?'Belegübernahme berichtigt':'Beleg übernommen')) ?></h3><p><?= e($item['description']) ?></p><?php if($item['reason']!==''): ?><p><?= e($item['reason']) ?></p><?php endif ?><a class="btn btn-outline" data-annual-source-history-link="<?= e($item['sha256']) ?>" href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'balance_source'=>$item['type'].':'.$item['id'],'source_original'=>(string)$item['revision'],'source_original_sha256'=>$item['sha256']])) ?>"><?= e($annualSourceText('Diesen ursprünglichen Ausgang lesen')) ?></a></article><?php endforeach ?>
<?php if($annualHistory['pages']>1): ?><nav aria-label="<?= e($annualSourceText('Verlauf der Belegübernahmen')) ?>"><p><?= e($annualSourceText('Seite')) ?> <?= $annualHistory['page'] ?> / <?= $annualHistory['pages'] ?></p><?php if($annualHistory['page']>1): ?><a class="btn btn-outline" href="<?= e($annualHistoryUrl($annualHistory['page']-1)) ?>"><?= e($annualSourceText('Neuere Entscheidungen')) ?></a><?php endif ?><?php if($annualHistory['page']<$annualHistory['pages']): ?><a class="btn btn-outline" href="<?= e($annualHistoryUrl($annualHistory['page']+1)) ?>"><?= e($annualSourceText('Frühere Entscheidungen')) ?></a><?php endif ?></nav><?php endif ?><?php endif ?></details>
